#include <algorithm>
#include <cstddef>
#include <span>

float DotProduct(std::span<const float> lhs, std::span<const float> rhs)
{
    const std::size_t count = std::min(lhs.size(), rhs.size());
    float sum = 0.0f;
    for (std::size_t index = 0; index < count; ++index)
    {
        sum += lhs[index] * rhs[index];
    }
    return sum;
}

The loop is intentionally simple: an optimizing compiler can vectorize it, while the size check keeps the public function well-defined for unequal spans.
